create or replace function public.set_vitoria_knowledge_source_status(p_organization_id uuid,p_source_id uuid,p_status text) returns void language plpgsql security definer set search_path='' as $f$ begin if p_status not in ('pending','processing','completed','failed') then raise exception 'VITORIA_KNOWLEDGE_STATUS_INVALID'; end if; update crm_private.vitoria_knowledge_sources set vector_file_status=p_status,updated_at=now() where organization_id=p_organization_id and id=p_source_id; if not found then raise exception 'VITORIA_KNOWLEDGE_NOT_FOUND'; end if; end $f$; revoke all on function public.set_vitoria_knowledge_source_status(uuid,uuid,text) from public,anon,authenticated; grant execute on function public.set_vitoria_knowledge_source_status(uuid,uuid,text) to service_role;
